def listProjects(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0291000" if __import__("os").path.isdir("./environment_mix/0291000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{s}"

    def _parse_ts(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1])
            return datetime.datetime.fromisoformat(v)
        except ValueError:
            return None

    # tool_name is constrained by schema; vendor logs only "hello" and "generateImage"
    _LOG_TOOL_NAME = "hello"

    t0 = time.time()
    response_status = 500
    project_id_for_log = None

    # Validate inputs
    if status is not None:
        if not isinstance(status, str):
            response_status = 400
        elif status not in ("active", "suspended", "deleted"):
            response_status = 400

        if response_status == 400:
            # log then return
            logs = _load("api_call_logs.json")
            now = _now()
            logs.append({
                "id": _gen_id("jmg_log"),
                "project_id": None,
                "tool_name": _LOG_TOOL_NAME,
                "request_payload": {},
                "response_status": 400,
                "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
                "generation_request_id": None,
                "client_ip": None,
                "user_agent": None,
                "created_at": now,
                "updated_at": now,
            })
            _save("api_call_logs.json", logs)
            if not isinstance(status, str):
                return _err("VALIDATION_ERROR", "Field 'status' must be a string.", field="status")
            return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, suspended, deleted.", field="status", value=status)

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        response_status = 400
    elif limit < 1 or limit > 200:
        response_status = 400

    if response_status == 400:
        logs = _load("api_call_logs.json")
        now = _now()
        logs.append({
            "id": _gen_id("jmg_log"),
            "project_id": None,
            "tool_name": _LOG_TOOL_NAME,
            "request_payload": {},
            "response_status": 400,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "generation_request_id": None,
            "client_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("api_call_logs.json", logs)
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "Field 'limit' must be an integer.", field="limit")
        return _err("VALIDATION_ERROR", "Field 'limit' must be between 1 and 200.", field="limit", value=limit)

    if cursor is not None and not isinstance(cursor, str):
        logs = _load("api_call_logs.json")
        now = _now()
        logs.append({
            "id": _gen_id("jmg_log"),
            "project_id": None,
            "tool_name": _LOG_TOOL_NAME,
            "request_payload": {},
            "response_status": 400,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
            "generation_request_id": None,
            "client_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("api_call_logs.json", logs)
        return _err("VALIDATION_ERROR", "Field 'cursor' must be a string.", field="cursor")

    # Load and filter
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    filtered = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if status is not None and p.get("status") != status:
            continue
        filtered.append(p)

    # Sort by most recently updated (desc), then id (desc) for stability
    def _sort_key(p):
        ts = _parse_ts(p.get("updated_at")) or _parse_ts(p.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (ts, str(p.get("id") or ""))

    filtered.sort(key=_sort_key, reverse=True)

    # Cursor semantics: opaque id of the last item from previous page
    start_idx = 0
    if cursor:
        # Do not error for unknown/foreign cursor; treat as "start from beginning" if not found.
        # If found, start after it.
        for i, p in enumerate(filtered):
            if p.get("id") == cursor:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    response_status = 200
    # Log call
    logs = _load("api_call_logs.json")
    now = _now()
    logs.append({
        "id": _gen_id("jmg_log"),
        "project_id": project_id_for_log,
        "tool_name": _LOG_TOOL_NAME,
        "request_payload": {},
        "response_status": response_status,
        "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
        "generation_request_id": None,
        "client_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("api_call_logs.json", logs)

    return {
        "projects": page,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor
    }

