        "user_agent": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("api_call_logs.json", logs)

    return resp

def updateProject(id, name=None, default_provider_id=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0291000" if __import__("os").path.isdir("./environment_mix/0291000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(20))
        return f"{prefix}_{s}"

    t0 = time.time()
    response_status = 500
    project_id_for_log = None
    resp = None

    # Validate id strictly per tool schema
    if not isinstance(id, str):
        response_status = 400
        resp = _err("VALIDATION_ERROR", "Field 'id' must be a string.", field="id", value=id)
    elif re.match(r"^jmg_prj_[0-9A-Z]{18,}$", id) is None:
        response_status = 400
        resp = _err("VALIDATION_ERROR", "Malformed project id.", field="id", value=id, pattern_expected="^jmg_prj_[0-9A-Z]{18,}$")
    else:
        # Validate optional fields (types/enums)
        if name is not None and not isinstance(name, str):
            response_status = 400
            resp = _err("VALIDATION_ERROR", "Field 'name' must be a string.", field="name", value=name)
        elif name is not None and not (1 <= len(name.strip()) <= 200):
            response_status = 400
            resp = _err("VALIDATION_ERROR", "Field 'name' length must be between 1 and 200.", field="name", value=name)
        elif default_provider_id is not None and not isinstance(default_provider_id, str):
            # Note: tool schema marks nullable; signature doesn't provide a sentinel; None is treated as "not provided" here.
            response_status = 400
            resp = _err("VALIDATION_ERROR", "Field 'default_provider_id' must be a string or null.", field="default_provider_id", value=default_provider_id)
        elif isinstance(default_provider_id, str) and re.match(r"^jmg_prv_[0-9A-Z]{18,}$", default_provider_id) is None:
            response_status = 400
            resp = _err("VALIDATION_ERROR", "Malformed provider id.", field="default_provider_id", value=default_provider_id, pattern_expected="^jmg_prv_[0-9A-Z]{18,}$")
        elif status is not None and (not isinstance(status, str) or status not in ("active", "suspended", "deleted")):
            response_status = 400
            resp = _err("VALIDATION_ERROR", "Field 'status' must be one of: active, suspended, deleted.", field="status", value=status)
        else:
            projects = _load("projects.json")
            if not isinstance(projects, list):
                projects = []
            providers = _load("providers.json")
            if not isinstance(providers, list):
                providers = []

            idx = next((i for i, p in enumerate(projects) if isinstance(p, dict) and p.get("id") == id), None)
            if idx is None:
                response_status = 404
                resp = _err("NOT_FOUND", "Project not found.", id=id)
            else:
                proj = projects[idx]
                project_id_for_log = proj.get("id")

                # Apply changes with constraints
                changed = False

                if name is not None:
                    new_name = name.strip()
                    # unique(name)
                    if any(isinstance(p, dict) and p.get("id") != id and p.get("name") == new_name for p in projects):
                        response_status = 409
                        resp = _err("CONFLICT", "Project name already exists (unique(name)).", field="name", value=new_name)
                    else:
                        if proj.get("name") != new_name:
                            proj["name"] = new_name
                            changed = True

                if resp is None and default_provider_id is not None:
                    # Must reference existing provider if non-null
                    prv = next((r for r in providers if isinstance(r, dict) and r.get("id") == default_provider_id), None)
                    if prv is None:
                        response_status = 404
                        resp = _err("NOT_FOUND", "Provider not found.", id=default_provider_id, field="default_provider_id")
                    else:
                        if proj.get("default_provider_id") != default_provider_id:
                            proj["default_provider_id"] = default_provider_id
                            changed = True

                if resp is None and status is not None:
                    cur = proj.get("status")
                    transitions = {
                        "active": ["suspended", "deleted"],
                        "suspended": ["active", "deleted"],
                        "deleted": [],
                    }
                    if cur not in transitions:
                        response_status = 400
                        resp = _err("VALIDATION_ERROR", "Project has invalid current status.", field="status", value=cur)
                    elif status == cur:
                        # idempotent
                        pass
                    elif status not in transitions[cur]:
                        response_status = 409
                        resp = _err("INVALID_TRANSITION", "Illegal project status transition.", from_status=cur, to_status=status)
                    else:
                        proj["status"] = status
                        changed = True

                if resp is None:
                    if not changed:
                        # no success without effect: if nothing changed, return current row as idempotent update (real APIs often do)
                        # but ensure this is not a "matched no row" situation (it did match)
                        response_status = 200
                        resp = {"project": proj}
                    else:
                        proj["updated_at"] = _now()
                        projects[idx] = proj
                        _save("projects.json", projects)
                        response_status = 200
                        resp = {"project": proj}

    # Log call (schema only allows hello/generateImage => use hello)
    logs = _load("api_call_logs.json")
    if not isinstance(logs, list):
        logs = []
    now = _now()
    logs.append({
        "id": _gen_id("jmg_log"),
        "project_id": project_id_for_log,
        "tool_name": "hello",
        "request_payload": {},
        "response_status": int(response_status),
        "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
        "generation_request_id": None,
        "client_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("api_call_logs.json", logs)

    return resp

