                "failed": [],
                "cancelled": [],
            }

            if cur not in transitions:
                response_status = 400
                resp = _err("VALIDATION_ERROR", "Generation request has invalid current status.", field="status", value=cur)
            elif status == cur:
                # idempotent: already cancelled
                response_status = 200
                resp = {"generation_request": grq}
            elif status not in transitions[cur]:
                response_status = 409
                resp = _err("INVALID_TRANSITION", "Illegal generation request status transition.", from_status=cur, to_status=status)
            else:
                # Only allow caller cancellation from queued/running per tool description
                if cur not in ("queued", "running"):
                    response_status = 409
                    resp = _err("INVALID_TRANSITION", "Only queued or running requests may be cancelled.", from_status=cur, to_status="cancelled")
                else:
                    # Apply transition: cancelled is terminal; set finished_at, error metadata if not already set
                    now = _now()
                    grq["status"] = "cancelled"
                    grq["updated_at"] = now
                    if grq.get("finished_at") is None:
                        grq["finished_at"] = now
                    if grq.get("error_code") is None:
                        grq["error_code"] = "USER_CANCELLED"
                    if grq.get("error_message") is None:
                        grq["error_message"] = "Cancelled by user."
                    reqs[idx] = grq
                    _save("generation_requests.json", reqs)
                    response_status = 200
                    resp = {"generation_request": grq}

    # Log call (schema only allows hello/generateImage => use hello)
    logs = _load("api_call_logs.json")
    if not isinstance(logs, list):
        logs = []
    now = _now()
    logs.append({
        "id": _gen_id("jmg_log"),
        "project_id": project_id_for_log,
        "tool_name": "hello",
        "request_payload": {},
        "response_status": int(response_status),
        "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
        "generation_request_id": None,
        "client_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("api_call_logs.json", logs)

    return resp
